if (head->value == value) {
    ListNode* toDelete = head;
    head = head->next;
    delete toDelete;
    return true;
}
ListNode* prev = head;
ListNode* cur = head->next;
while (cur) {
    if (cur->value == value) {
        prev->next = cur->next;
        delete cur;
        return true;
    }
    prev = cur;
    cur = cur->next;
}
